Method.Implementation:
Set tStatus = $$$OK
Try {
	If $IsObject(..RecordX) {
		Set tStatus = ##class(IHC.ITF.DStruc.ShKeyWordRecX).PutObject(pIOStream,..RecordX,0)
		If $$$ISERR(tStatus) Quit
	}
	If $IsObject(..RecordO) {
		Set tStatus = ##class(IHC.ITF.DStruc.ShKeyWordRecO).PutObject(pIOStream,..RecordO,0)
		If $$$ISERR(tStatus) Quit
	}
	If $IsObject(..RecordCDSD) {
		Set tStatus = ##class(IHC.ITF.DStruc.ShKeyWordRecCDSD).PutObject(pIOStream,..RecordCDSD,0)
		If $$$ISERR(tStatus) Quit
	}
}
Catch {
	Set tStatus = $$$SystemError
}
Quit tStatus

